export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const tApex = u / g;
  const yApex = (u * u) / (2 * g);

  const t = time;
  const tRel = Math.max(0, t - tApex);

  const yToss = Math.max(0, u * t - 0.5 * g * t * t);
  const vToss = u - g * t;
  const aToss = -g;

  let yDrop = yApex;
  let vDrop = 0;
  let aDrop = 0;

  if (t >= tApex) {
    yDrop = Math.max(0, yApex - 0.5 * g * tRel * tRel);
    vDrop = -g * tRel;
    aDrop = -g;
  }

  let stateToss = "At launch";
  if (t > 0 && t < tApex - 0.01) stateToss = "Rising";
  else if (Math.abs(t - tApex) <= 0.01) stateToss = "At the top";
  else if (t > tApex + 0.01 && yToss > 0) stateToss = "Falling";
  else if (t > 0 && yToss <= 0) stateToss = "At launch height";

  let stateDrop = "Held in place";
  if (Math.abs(t - tApex) <= 0.01) stateDrop = "Just released";
  else if (t > tApex + 0.01 && yDrop > 0) stateDrop = "Falling together";
  else if (t > tApex && yDrop <= 0) stateDrop = "At launch height";

  const objects = [];

  const tossPanel = sdk.panel({
    id: "lane.toss",
    x: 20,
    y: 30,
    w: 285,
    h: 360,
    title: "Toss lane",
    state: stateToss
  });
  const dropPanel = sdk.panel({
    id: "lane.drop",
    x: 335,
    y: 30,
    w: 285,
    h: 360,
    title: "Drop lane",
    state: stateDrop
  });
  objects.push(...tossPanel, ...dropPanel);

  const yMinPx = 330;
  const yMaxPx = 90;
  const hScale = (yMinPx - yMaxPx) / 2.2;

  const pxTossY = yMinPx - yToss * hScale;
  const pxDropY = yMinPx - yDrop * hScale;
  const pxApexY = yMinPx - yApex * hScale;

  const axisToss = sdk.axis("axis.toss", {
    x: 50,
    y: yMinPx,
    length: yMinPx - yMaxPx,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  });
  const axisDrop = sdk.axis("axis.drop", {
    x: 365,
    y: yMinPx,
    length: yMinPx - yMaxPx,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  });
  objects.push(axisToss, axisDrop);

  if (t >= tApex) {
    objects.push(
      sdk.circle("ghost.toss", 175, pxApexY, 26, { role: "neutral", opacity: 0.35 }),
      sdk.circle("ghost.drop", 490, pxApexY, 26, { role: "neutral", opacity: 0.35 })
    );
  }

  const gateObjs = sdk.gate("gate", 490, pxApexY, { open: t >= tApex, w: 36, label: "Release" });
  objects.push(...gateObjs);

  const ballToss = sdk.circle("ball.toss", 175, pxTossY, 26, { role: "learner" });
  const ballDrop = sdk.circle("ball.drop", 490, pxDropY, 26, { role: "tutor" });
  objects.push(ballToss, ballDrop);

  const vScale = 18;
  const aScale = 5;

  const vecVToss = sdk.vector("vec.v.toss", { x: 155, y: pxTossY }, { value: vToss, direction: "up" }, { scale: vScale, label: "v", role: "learner" });
  const vecVDrop = sdk.vector("vec.v.drop", { x: 470, y: pxDropY }, { value: vDrop, direction: "up" }, { scale: vScale, label: "v", role: "tutor" });
  const vecAToss = sdk.vector("vec.a.toss", { x: 195, y: pxTossY }, { value: aToss, direction: "up" }, { scale: aScale, label: "a", role: "warning" });
  const vecADrop = sdk.vector("vec.a.drop", { x: 510, y: pxDropY }, { value: aDrop, direction: "up" }, { scale: aScale, label: "a", role: "warning" });
  objects.push(...vecVToss, ...vecVDrop, ...vecAToss, ...vecADrop);

  const calloutToss = sdk.callout(210, pxTossY - 20, [`v: ${vToss.toFixed(2)} m/s`, `a: ${aToss.toFixed(2)} m/s²`], { id: "callout.toss" });
  const calloutDrop = sdk.callout(525, pxDropY - 20, [`v: ${vDrop.toFixed(2)} m/s`, `a: ${aDrop.toFixed(2)} m/s²`], { id: "callout.drop" });
  objects.push(calloutToss, calloutDrop);

  return {
    frame: sdk.frame(objects, {
      readouts: [
        { id: "tossedVelocity", value: vToss },
        { id: "tossedAcceleration", value: aToss },
        { id: "dropVelocity", value: vDrop },
        { id: "dropAcceleration", value: aDrop }
      ]
    }),
    quantities: {
      launchSpeed: u,
      gravity: g,
      apexTime: tApex,
      apexHeight: yApex,
      tossedVelocity: vToss,
      tossedAcceleration: aToss,
      tossedHeight: yToss,
      dropVelocity: vDrop,
      dropAcceleration: aDrop,
      dropHeight: yDrop
    }
  };
}
